/**
 * CSS animations for the UI library
 */

export const animations = {
  slideInRight: `
    @keyframes slideInRight {
      from {
        transform: translateX(100%);
        opacity: 0;
      }
      to {
        transform: translateX(0);
        opacity: 1;
      }
    }
  `,
  slideOutRight: `
    @keyframes slideOutRight {
      from {
        transform: translateX(0);
        opacity: 1;
      }
      to {
        transform: translateX(100%);
        opacity: 0;
      }
    }
  `,
  fadeInScale: `
    @keyframes fadeInScale {
      from {
        opacity: 0;
        transform: scale(0.95);
      }
      to {
        opacity: 1;
        transform: scale(1);
      }
    }
  `,
  fadeOutScale: `
    @keyframes fadeOutScale {
      from {
        opacity: 1;
        transform: scale(1);
      }
      to {
        opacity: 0;
        transform: scale(0.95);
      }
    }
  `,
  slideDownFade: `
    @keyframes slideDownFade {
      from {
        opacity: 1;
        transform: translateY(0) scale(1);
      }
      to {
        opacity: 0;
        transform: translateY(20px) scale(0.98);
      }
    }
  `,
  fadeIn: `
    @keyframes fadeIn {
      from {
        opacity: 0;
      }
      to {
        opacity: 1;
      }
    }
  `,
  fadeOut: `
    @keyframes fadeOut {
      from {
        opacity: 1;
      }
      to {
        opacity: 0;
      }
    }
  `,
  spin: `
    @keyframes spin {
      from {
        transform: rotate(0deg);
      }
      to {
        transform: rotate(360deg);
      }
    }
  `,
  progressFill: `
    @keyframes progressFill {
      from {
        width: 0%;
      }
    }
  `
};

/**
 * Inject animations into the document head
 */
export function injectAnimations(targetDoc?: Document): void {
  const styleId = 'err403-animations';
  const doc = targetDoc || document;
  
  // Check if already injected in target document
  if (doc.getElementById(styleId)) {
    return;
  }
  
  const style = doc.createElement('style');
  style.id = styleId;
  style.textContent = Object.values(animations).join('\n');
  doc.head.appendChild(style);
}
